use super::*;

struct OriginalCaller{issuer:semio_framework_job::StepContextOwner,cancel:semio_framework_job::CancelToken,sequence:u64,last:RetainedCloneProgress}
impl OriginalCaller{
 fn new()->Self{let birth=semio_framework_job::StepContextOwner::birth_bytes();let(issuer,_)=semio_framework_job::StepContextOwner::new(semio_framework_job::OperationId(707),semio_framework_job::Generation(9),RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:birth,maximum_depth:1,..Default::default()}).unwrap();Self{issuer,cancel:semio_framework_job::root_cancel_token(),sequence:0,last:Default::default()}}
 fn run<T>(&mut self,grant:RetainedCloneGrant,step:impl FnOnce(&mut semio_framework_job::StepContext<'_>)->T)->T{let mut receipt=Default::default();let mut cx=self.issuer.context(semio_framework_job::StepBudget::new(1,u64::MAX,grant),self.cancel.clone(),||Some(1),&mut self.sequence,&mut receipt).unwrap();let result=step(&mut cx);self.last=cx.retained_progress();assert!(self.last.fits(grant));assert!(cx.fuel_remaining()<=1);result}
}
impl Drop for OriginalCaller{fn drop(&mut self){self.issuer.close_step(RetainedCloneGrant{maximum_items:1,maximum_release_bytes:semio_framework_job::StepContextOwner::birth_bytes(),maximum_depth:1,..Default::default()});assert!(self.issuer.terminal_is_empty());}}

fn observe<T>(operation:impl FnOnce()->T)->(T,usize,usize){semio_framework_os_kernel_neural_engine_model::testkit::observe_ownership(operation)}

#[derive(semio_framework_value::RetireOwned)]
struct FinishedChannels(EvalChannels);

#[test]
fn original_budgeted_eval_normal_boundary_turns_match_oracle_and_cancel_same_source(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){for copy in [1,3,64]{for cancel_at in [None,Some(0),Some(9),Some(37),Some(101)]{
  let((tree,seeds,dirty,infos,registry,mut registry_retirement),born,free)=observe(||{let tree=Arc::new(Tree{neurons:row["nodes"].as_array().unwrap().iter().map(|node|crate::Neuron::with_kind(node["id"].as_str().unwrap(),node["kind"].as_str().unwrap(),serde_json::from_value::<Dictionary>(node["params"].clone()).unwrap())).collect(),synapses:row["edges"].as_array().unwrap().iter().map(|edge|crate::Synapse{id:String::new(),from:edge[0].as_str().unwrap().into(),to:edge[1].as_str().unwrap().into(),from_port:edge.get(2).and_then(serde_json::Value::as_str).unwrap_or_default().into(),to_port:edge.get(3).and_then(serde_json::Value::as_str).unwrap_or_default().into()}).collect()});let seeds=Arc::new(row["seeds"].as_object().unwrap().iter().map(|(key,value)|(key.clone(),serde_json::from_value::<Dictionary>(value.clone()).unwrap())).collect());let dirty=tree.neurons.iter().map(|node|(node.id.clone(),())).collect();let infos=Arc::new(HistoryFoldIndex::new());let(registry,retirement)=SharedRegistry::new(crate::Registry::new());(tree,seeds,dirty,infos,registry,retirement)});let original=born-free;let source=Arc::as_ptr(&tree);
  let((mut state,registry),born,free)=observe(||{let authority=registry.clone();(BudgetedEvalState::new(tree,seeds,dirty,infos,registry,None),authority)});assert_eq!((born,free),(0,0));let mut births=0;let mut releases=0;let mut result=None;let mut idle=0;let mut original_caller=OriginalCaller::new();
  for turn in 0..1000000{if cancel_at==Some(turn){break;}let demand=state.next_step_demands(copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};for _ in 0..2{let(step,born,free)=observe(||original_caller.run(RetainedCloneGrant{maximum_items:0,..grant},|cx|state.step(cx)).unwrap());assert!(matches!(step,BudgetedEvalStep::Working));assert_eq!(state.normal_step_progress(),Default::default());assert_eq!((born,free),(0,0));}let(step,born,free)=observe(||original_caller.run(grant,|cx|state.step(cx)).unwrap());let progress=state.normal_step_progress();assert_eq!(progress,original_caller.last);assert!(progress.fits(grant),"phase={} grant={grant:?} progress={progress:?}",state.phase);assert_eq!((born,free),(progress.retained_capacity_bytes,progress.released_bytes),"phase={} turn={turn}",state.phase);births+=born;releases+=free;assert_eq!(Arc::as_ptr(state.source().unwrap()),source);if let BudgetedEvalStep::Complete(output)=step{result=Some(output);break;}if progress==RetainedCloneProgress::default(){idle+=1}else{idle=0}assert!(idle<64,"normal stall phase={} turn={turn} copy={copy} demand={demand:?}",state.phase);}
  if cancel_at.is_none(){let output=result.as_ref().expect("normal evaluation did not complete");let inputs:std::collections::BTreeMap<_,_>=output.channels.inputs.iter().map(|(key,value)|(key,serde_json::to_value(value).unwrap())).collect();let outputs:std::collections::BTreeMap<_,_>=output.channels.outputs.iter().map(|(key,value)|(key,serde_json::to_value(value).unwrap())).collect();assert_eq!(serde_json::to_value(inputs).unwrap(),row["expectedInputs"]);assert_eq!(serde_json::to_value(outputs).unwrap(),row["expectedOutputs"]);}
  let(mut output,born,free)=observe(||result.map(|output|{assert!(output.remaining.is_empty()&&output.pending_extensions.is_empty());ControlledRetirement::new(FinishedChannels(output.channels)).unwrap_or_else(|_|unreachable!())}));assert_eq!((born,free),(0,0));let(_,born,free)=observe(||{state.begin_close();drop(registry)});assert_eq!((born,free),(0,0));
  let mut close_idle=0;for close_turn in 0..1000000{if state.terminal_is_empty(){break;}let demand=state.next_close_demands(copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let(step,born,free)=observe(||state.close_step(grant).unwrap());assert_eq!(state.normal_step_progress(),step.progress());assert!(step.progress().fits(grant));assert_eq!((born,free),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=born;releases+=free;if step.progress()==RetainedCloneProgress::default(){close_idle+=1}else{close_idle=0}assert!(close_idle<64,"original normal-close stalled id={} cancel={cancel_at:?} copy={copy} turn={close_turn} phase={} owner={} retirement={} demand={demand:?} progress={:?}",row["id"],state.phase,state.owners.is_some(),state.retirement.is_some(),step.progress());}assert!(state.terminal_is_empty());let(_,born,free)=observe(||drop(state));assert_eq!((born,free),(0,0));
  if let Some(owner)=output.as_mut(){for _ in 0..1000000{if owner.terminal_is_empty(){break;}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,born,free)=observe(||owner.step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((born,free),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=born;releases+=free;}assert!(owner.terminal_is_empty());}let(_,born,free)=observe(||drop(output));assert_eq!((born,free),(0,0));
  for _ in 0..1000000{if registry_retirement.terminal_is_empty(){break;}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:registry_retirement.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:registry_retirement.next_release_byte_demand().unwrap(),maximum_depth:registry_retirement.next_depth_demand().unwrap()};let(step,born,free)=observe(||registry_retirement.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((born,free),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=born;releases+=free;}assert!(registry_retirement.terminal_is_empty());assert_eq!(original+births,releases);let(_,born,free)=observe(||drop(registry_retirement));assert_eq!((born,free),(0,0));eprintln!("[DEBUG] Original eval normal id={} copy={copy} cancel={cancel_at:?} original={original} born={births} release={releases} terminalDrop=0",row["id"]);
 }}}
}

#[test]
fn original_budgeted_eval_state_preserves_complete_source_roster_and_closes_with_physical_receipts(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){for copy in [1,3,64]{
  let((tree,seeds,dirty,infos,registry,mut registry_retirement,previous),born,free)=observe(||{let tree=Arc::new(Tree{neurons:row["nodes"].as_array().unwrap().iter().map(|node|crate::Neuron::with_kind(node["id"].as_str().unwrap(),node["kind"].as_str().unwrap(),serde_json::from_value::<Dictionary>(node["params"].clone()).unwrap())).collect(),synapses:row["edges"].as_array().unwrap().iter().map(|edge|crate::Synapse{id:String::new(),from:edge[0].as_str().unwrap().into(),to:edge[1].as_str().unwrap().into(),from_port:edge.get(2).and_then(serde_json::Value::as_str).unwrap_or_default().into(),to_port:edge.get(3).and_then(serde_json::Value::as_str).unwrap_or_default().into()}).collect()});let seeds=Arc::new(row["seeds"].as_object().unwrap().iter().map(|(key,value)|(key.clone(),serde_json::from_value::<Dictionary>(value.clone()).unwrap())).collect());let dirty=tree.neurons.iter().map(|node|(node.id.clone(),())).collect();let infos=Arc::new([(String::from("preborn-kind"),OperatorInfo{id:"same original metadata".into(),..Default::default()})].into_iter().collect());let(registry,retirement)=SharedRegistry::new(crate::Registry::new());let previous=Arc::new(EvalChannels{inputs:row["expectedInputs"].as_object().unwrap().iter().map(|(key,value)|(key.clone(),serde_json::from_value::<Dictionary>(value.clone()).unwrap())).collect(),outputs:row["expectedOutputs"].as_object().unwrap().iter().map(|(key,value)|(key.clone(),serde_json::from_value::<Dictionary>(value.clone()).unwrap())).collect()});(tree,seeds,dirty,infos,registry,retirement,Some(previous))});let original=born-free;let source=Arc::as_ptr(&tree);
  let(mut state,born,free)=observe(||BudgetedEvalState::new(tree,seeds,dirty,infos,registry,previous));assert_eq!((born,free),(0,0));assert_eq!(Arc::as_ptr(state.source().unwrap()),source);let(_,born,free)=observe(||state.begin_close());assert_eq!((born,free),(0,0));let mut births=0;let mut releases=0;let mut idle=0;let mut original_caller=OriginalCaller::new();
  for turn in 0..1000000{if state.terminal_is_empty(){break;}let demand=state.next_close_demands(copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};for _ in 0..2{let(step,born,free)=observe(||state.close_step(RetainedCloneGrant{maximum_items:0,..grant}).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(state.normal_step_progress(),step.progress());assert_eq!((born,free),(0,0));}let(step,born,free)=observe(||state.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!(state.normal_step_progress(),step.progress());assert_eq!((born,free),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=born;releases+=free;if step.progress()==RetainedCloneProgress::default(){idle+=1}else{idle=0}assert!(idle<64,"original state close stalled copy={copy} turn={turn} demand={demand:?}");}
  assert!(state.terminal_is_empty());let(_,born,free)=observe(||drop(state));assert_eq!((born,free),(0,0));
  for _ in 0..1000000{if registry_retirement.terminal_is_empty(){break;}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:registry_retirement.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:registry_retirement.next_release_byte_demand().unwrap(),maximum_depth:registry_retirement.next_depth_demand().unwrap()};let(step,born,free)=observe(||registry_retirement.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((born,free),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=born;releases+=free;}
  assert!(registry_retirement.terminal_is_empty());assert_eq!(original+births,releases);let(_,born,free)=observe(||drop(registry_retirement));assert_eq!((born,free),(0,0));eprintln!("[DEBUG] Original eval custody id={} copy={copy} original={original} born={births} release={releases} terminalDrop=0",row["id"]);
 }}
}

#[global_allocator]
static OBSERVED_SYSTEM:semio_framework_os_kernel_neural_engine_model::testkit::ObservedSystem=semio_framework_os_kernel_neural_engine_model::testkit::ObservedSystem;

//#region 🧠️CacheRetirement
fn cache_grant(owner:&crate::NeuralCacheRetirement,copy:usize)->RetainedCloneGrant {
    RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()}
}
#[test]
fn cache_retirement_preserves_shared_roots_and_drains_replaced_nested_values() {
    use semio_framework_os_kernel_neural_engine_model::testkit::observe_ownership;
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧵️retirement/🧪️tests/🧫️fixtures/🗃️cache-retirement/🔣️.json")).unwrap();
    let seeds:Vec<_>=fixture["operations"].as_array().unwrap().iter().filter(|value|value["op"]=="seed").collect();
    let payload:usize=seeds.iter().map(|seed|seed["field"].as_str().unwrap().len()+seed["text"].as_str().unwrap().len()*seed["repeat"].as_u64().unwrap()as usize).sum();assert_eq!(payload,fixture["expected"]["finalReleasedBytes"].as_u64().unwrap()as usize);
    for copy in [1,64,4096] {
        let (_,born,freed)=observe_ownership(|| {
            let cache=Arc::new(crate::NeuralCache::new());
            for seed in &seeds {cache.seed(fixture["key"].as_u64().unwrap(),Dictionary::new().insert(seed["field"].as_str().unwrap(),Value::Atom(Atom::String(seed["text"].as_str().unwrap().repeat(seed["repeat"].as_u64().unwrap()as usize))))).unwrap();}
            let mut shared=crate::NeuralCacheRetirement::new(Arc::clone(&cache));
            for _ in 0..100 {if shared.terminal_is_empty(){break;}let grant=cache_grant(&shared,copy);let (step,a,r)=observe_ownership(||shared.close_step(grant).unwrap());assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),(a,r));assert_eq!(r,0);}
            assert!(shared.terminal_is_empty());assert_eq!(cache.len(),1);
            let mut owner=crate::NeuralCacheRetirement::new(cache);
            for _ in 0..1000000 {
                if owner.terminal_is_empty(){break;}let grant=cache_grant(&owner,copy);
                let (zero,a,r)=observe_ownership(||owner.close_step(RetainedCloneGrant {maximum_items:0,..grant}).unwrap());assert_eq!(zero.progress(),RetainedCloneProgress::default());assert_eq!((a,r),(0,0));
                let (step,a,r)=observe_ownership(||owner.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),(a,r));
            }
            assert!(owner.terminal_is_empty());
        });assert_eq!(born,freed);eprintln!("[DEBUG] Original Neural cache copy={copy} alias/replacement/final allocations closed={freed}");
    }
}
#[test]
fn cache_live_final_drop_is_guarded_instead_of_recursively_destroying_dictionaries() {
    assert!(std::panic::catch_unwind(||{let cache=crate::NeuralCache::new();cache.seed(1,Dictionary::new().insert("label",Value::Atom(Atom::String("guarded".into())))).unwrap();drop(cache);}).is_err());
}
